<?php
namespace App\Http\Controllers; use App\Models\{Laboratory,LetterRequest,LetterRequestHistory,LetterRequirementSubmission,LetterType}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class LetterProcessController extends Controller {
 public function index(Request $r){ $user=$r->user(); $q=LetterRequest::with(['letterType.workflowSteps','applicant','laboratory']); if($user->role==='admin'){} elseif($user->role==='kepala_labor'||$user->role==='tenaga_labor'){ $q->where(function($x) use($user){$x->where('applicant_id',$user->id)->orWhere('laboratory_id',$user->laboratory_id);}); } elseif($user->role==='prodi'){ /* prodi may monitor all */ } else { $q->where('applicant_id',$user->id); } $requests=$q->latest()->get(); return view('surat.index',compact('requests')); }
 public function create(){ return view('surat.create',['types'=>LetterType::with(['requirements','workflowSteps'])->where('is_active',true)->get(),'laboratories'=>Laboratory::all()]); }
 public function store(Request $r){ $d=$r->validate(['letter_type_id'=>'required|exists:letter_types,id','laboratory_id'=>'nullable|exists:laboratories,id','subject'=>'required|string|max:255','notes'=>'nullable|string|max:2000']); $type=LetterType::with(['requirements','workflowSteps'])->findOrFail($d['letter_type_id']); abort_if($type->workflowSteps->isEmpty(),422,'Jenis surat belum memiliki alur.'); foreach($type->requirements->where('is_required',true) as $req) $r->validate(['letter_req_'.$req->id=>'required|file|mimes:pdf,jpg,jpeg,png|max:2048']); $letter=null; DB::transaction(function() use($r,$d,$type,&$letter){ $letter=LetterRequest::create($d+['request_number'=>'SRT-'.now()->format('Ymd').'-'.strtoupper(Str::random(5)),'applicant_id'=>$r->user()->id,'status'=>'in_process','current_step_order'=>$type->workflowSteps->first()->step_order]); foreach($type->requirements as $req){ if($r->hasFile('letter_req_'.$req->id)){ $path=$r->file('letter_req_'.$req->id)->store('surat-syarat','public'); LetterRequirementSubmission::create(['letter_request_id'=>$letter->id,'letter_requirement_id'=>$req->id,'file_path'=>$path]); }} LetterRequestHistory::create(['letter_request_id'=>$letter->id,'step_order'=>null,'action'=>'submitted','actor_id'=>$r->user()->id,'actor_role'=>$r->user()->role,'notes'=>'Permohonan surat dibuat.']); }); return redirect()->route('surat.show',$letter)->with('success','Permohonan surat berhasil dibuat.'); }
 public function show(Request $r,LetterRequest $letterRequest){ $this->authorizeView($r,$letterRequest); $letterRequest->load(['letterType.workflowSteps','letterType.requirements','applicant','laboratory','histories.actor','files.requirement']); $current=$letterRequest->letterType->workflowSteps->firstWhere('step_order',$letterRequest->current_step_order); return view('surat.show',compact('letterRequest','current')); }
 public function action(Request $r,LetterRequest $letterRequest){ $this->authorizeView($r,$letterRequest); $d=$r->validate(['action'=>'required|in:approve,reject','notes'=>'nullable|string|max:1000']); $letterRequest->load('letterType.workflowSteps'); $current=$letterRequest->letterType->workflowSteps->firstWhere('step_order',$letterRequest->current_step_order); abort_unless($current && $current->role===$r->user()->role,403,'Surat belum berada pada tahapan role Anda.'); DB::transaction(function() use($r,$d,$letterRequest,$current){ LetterRequestHistory::create(['letter_request_id'=>$letterRequest->id,'step_order'=>$current->step_order,'action'=>$d['action'],'actor_id'=>$r->user()->id,'actor_role'=>$r->user()->role,'notes'=>$d['notes']??null]); if($d['action']==='reject'){ $letterRequest->update(['status'=>'rejected']); return; } $next=$letterRequest->letterType->workflowSteps->first(fn($s)=>$s->step_order>$current->step_order); if($next) $letterRequest->update(['current_step_order'=>$next->step_order]); else $letterRequest->update(['status'=>'completed','completed_at'=>now()]); }); return back()->with('success','Tahapan surat berhasil diproses.'); }
 private function authorizeView(Request $r,LetterRequest $l): void { $u=$r->user(); if(in_array($u->role,['admin','prodi'],true)) return; if($l->applicant_id===$u->id) return; if(in_array($u->role,['tenaga_labor','kepala_labor'],true)&&$l->laboratory_id===$u->laboratory_id) return; abort(403); }
}
